<?php declare(strict_types=1);$roleAction=(string)($_GET['action']??'');$rolePermissionStmt=$db->prepare('SELECT p.permission_key FROM role_permissions rp JOIN permissions p ON p.id=rp.permission_id WHERE rp.role_id=? AND rp.allowed=1 ORDER BY p.module_name,p.action_name');$roleDetails=[];foreach($roles as $role){$rolePermissionStmt->execute([$role['id']]);$role['permission_keys']=$rolePermissionStmt->fetchAll(PDO::FETCH_COLUMN);$roleDetails[$role['code']]=$role;}$groups=['Company leadership'=>['OWNER','OPERATIONS_HEAD'],'Site operations'=>['SITE_SUPERVISOR','SITE_OPERATOR']];$known=array_merge(...array_values($groups));$custom=[];?>
<section class="page-title role-page-title"><div><span class="eyebrow">ACCESS CONTROL</span><h1>Job roles</h1><p class="muted">Four clear roles control company-wide and assigned-site access.</p></div><div class="title-actions"><a class="button" href="?page=users">Manage users</a></div></section>
<?php if($roleAction==='create'):?><form class="form-card wide role-editor" method="post"><div class="editor-head"><div><h2>Create custom role</h2><p class="muted">Use this only when the ready-made job roles do not match the employee’s responsibilities.</p></div><a href="?page=roles">Cancel</a></div><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><div class="form-grid"><label class="field">Role name<input name="name" required></label><label class="field">Role code<input name="code" required></label><label class="field">Description<input name="description"></label></div><div class="permission-grid"><?php foreach($permissions as $permission):?><label><input type="checkbox" name="permission_ids[]" value="<?=e($permission['id'])?>"> <?=e($permission['permission_key'])?></label><?php endforeach;?></div><button class="button" name="add_role" value="1">Create role</button></form>
<?php else:?><?php foreach($groups as $label=>$codes):?><section class="role-group"><div class="role-group-head"><h2><?=e($label)?></h2><small><?=count(array_filter($codes,fn($code)=>isset($roleDetails[$code])))?> roles</small></div><div class="role-catalogue"><?php foreach($codes as $code):if(!isset($roleDetails[$code]))continue;$role=$roleDetails[$code];?><article class="role-card"><div class="role-card-top"><div><b><?=e($role['name'])?></b><small><?=e($role['code'])?></small></div><span class="pill"><?=(int)$role['permission_count']?> permissions</span></div><p><?=e($role['description'])?></p><details><summary>View access</summary><div class="permission-chips"><?php foreach($role['permission_keys'] as $key):?><span><?=e(str_replace('.',' · ',$key))?></span><?php endforeach;?></div></details></article><?php endforeach;?></div></section><?php endforeach;?><?php if($custom):?><section class="role-group"><div class="role-group-head"><h2>Custom roles</h2><small><?=count($custom)?> roles</small></div><div class="role-catalogue"><?php foreach($custom as $role):?><article class="role-card"><div class="role-card-top"><div><b><?=e($role['name'])?></b><small><?=e($role['code'])?></small></div><span class="pill"><?=(int)$role['permission_count']?> permissions</span></div><p><?=e($role['description'])?></p></article><?php endforeach;?></div></section><?php endif;?><?php endif;?>
